package ai.learnharness.android;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;import org.junit.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Live account probe runs ONLY with the explicit opt-in instrumentation argument. No credentials leave app storage. */
public class PlanSearchProbeDeviceTest {
 @Test public void explicitlyRequestedLivePlanSearch()throws Exception{
  Assume.assumeTrue("Live plan probe is opt-in", "true".equals(InstrumentationRegistry.getArguments().getString("runPlanSearchProbe")));
  var context=InstrumentationRegistry.getInstrumentation().getTargetContext();JSONObject report=new JSONObject().put("probe","ChatGPT plan built-in web search").put("at",java.time.Instant.now().toString());OpenAiHttp http=new OpenAiHttp();
  try{ChatGptAccounts accounts=ChatGptAccounts.get(context);JSONObject account=accounts.active();if(account==null || !account.optBoolean("connected") || !account.optBoolean("plan"))throw new IOException("No active connected ChatGPT plan account.");String model=account.optString("model");if(model.isEmpty())throw new IOException("No selected ChatGPT model.");report.put("model",model);
   ProviderClient.Reply reply=http.webSearch(model,accounts.token(account.getString("client_id"),http),"This is a user-requested connectivity test. Search the web, answer in one short sentence and cite a source.",new JSONArray().put(new JSONObject().put("role","user").put("content","Find the official Android developer documentation for the Storage Access Framework. Give its URL and a single-sentence description.")),"default",null,true);
   JSONArray output=reply.nativeOutput().getJSONArray("responses");JSONArray shapes=new JSONArray();report.put("eventTypes",reply.nativeOutput().optJSONArray("streamEventTypes"));for(int i=0;i<output.length();i++){JSONObject item=output.getJSONObject(i);JSONObject shape=new JSONObject().put("type",item.optString("type")).put("status",item.optString("status"));if(item.has("action"))shape.put("actionKeys",item.getJSONObject("action").names());if(item.has("content"))shape.put("contentTypes",item.getJSONArray("content").length());shapes.put(shape);}report.put("outputShapes",shapes);int searches=0,citations=0;for(int i=0;i<output.length();i++){JSONObject item=output.getJSONObject(i);if(item.optString("type").equals("web_search_call") && item.optString("status").equals("completed"))searches++;JSONArray parts=item.optJSONArray("content");for(int j=0;parts!=null && j<parts.length();j++){JSONArray annotations=parts.getJSONObject(j).optJSONArray("annotations");for(int k=0;annotations!=null && k<annotations.length();k++)if(annotations.getJSONObject(k).optString("type").equals("url_citation"))citations++;}}
   report.put("completedSearches",searches).put("citations",citations).put("inputTokens",reply.inputTokens()).put("outputTokens",reply.outputTokens()).put("status",searches>0 && citations>0?"supported":"unverified");
  }catch(OpenAiHttp.Failure error){report.put("status","rejected").put("http",error.status).put("code",error.code).put("parameter",error.param).put("requestId",error.requestId).put("shape",error.shape);}
  catch(Exception error){report.put("status","unavailable").put("error",error instanceof IOException?error.getMessage():error.getClass().getSimpleName());}
  finally{http.cancel();try(OutputStream out=context.openFileOutput("plan-search-probe.json",0)){out.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}android.os.Bundle status=new android.os.Bundle();status.putString("stream","\nPlan search probe: "+report.toString()+"\n");InstrumentationRegistry.getInstrumentation().sendStatus(0,status);}
 }
 @Test public void explicitlyRequestedOriginalResearchIntegration()throws Exception{
  Assume.assumeTrue("Live researcher probe is opt-in","true".equals(InstrumentationRegistry.getArguments().getString("runPlanResearchProbe")));var context=InstrumentationRegistry.getInstrumentation().getTargetContext();JSONObject report=new JSONObject().put("probe","Original researcher with ChatGPT built-in search");int[] searches={0};
  try{JSONObject route=NativeModels.forRole(context,"researcher");report.put("model",route.getString("model"));try(NativeModels models=new NativeModels(context,route,true);ResearchWeb web=new ResearchWeb()){
   JSONObject result=new ResearchAgent(context).run(new JSONObject().put("question","Which Android API lets an app browse a user-selected document directory? Identify the intent and link to the official Android documentation."),new LessonAgent.Model(){public ProviderClient.Reply complete(String prompt,JSONArray history,JSONArray tools)throws Exception{ProviderClient.Reply reply=models.complete(prompt,history,tools);JSONArray items=reply.nativeOutput().optJSONArray("responses");for(int i=0;items!=null && i<items.length();i++)if(items.getJSONObject(i).optString("type").equals("web_search_call") && items.getJSONObject(i).optString("status").equals("completed"))searches[0]++;return reply;}},new ResearchAgent.Web(){public JSONArray search(String query,int count){throw new AssertionError("Attempted separate search-provider fallback");}public ResearchWeb.Page fetch(String url)throws Exception{return web.fetch(url);}},null);
   report.put("completedSearches",searches[0]).put("sources",result.getJSONArray("sources").length()).put("steps",result.getInt("steps")).put("inputTokens",result.getLong("inputTokens")).put("outputTokens",result.getLong("outputTokens")).put("briefCharacters",result.getString("brief").length()).put("status",searches[0]>0 && result.getJSONArray("sources").length()>0?"supported":"unverified");
   if(report.getString("status").equals("supported") && "true".equals(InstrumentationRegistry.getArguments().getString("enablePlanSearch"))){context.getSharedPreferences("settings",0).edit().putString("searchEngine","chatgpt").commit();report.put("planSearchEnabled",true);}
  }}catch(OpenAiHttp.Failure error){report.put("status","rejected").put("http",error.status).put("code",error.code).put("parameter",error.param).put("requestId",error.requestId);}
  catch(Exception error){report.put("status","unavailable").put("error",error instanceof IOException?error.getMessage():error.getClass().getSimpleName());}
  finally{try(OutputStream out=context.openFileOutput("plan-research-probe.json",0)){out.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}android.os.Bundle status=new android.os.Bundle();status.putString("stream","\nPlan researcher probe: "+report.toString()+"\n");InstrumentationRegistry.getInstrumentation().sendStatus(0,status);}
  Assert.assertEquals(report.toString(),"supported",report.optString("status"));
 }
}
